 assert [c for c in calls if c not in orig_calls]==[ast.dump(n,include_attributes=False) for n in ast.walk(constructor) if isinstance(n,ast.Call) and isinstance(n.func,ast.Name) and n.func.id=='ValueError' and ast.literal_eval(n.args[0]) in ['Unknown event-order treatment','Unknown event-order orientation']] or variant['name']=='supplied_unchanged'
 for name,method in orig_methods.items():
  if name not in ('__init__','_represent'):
   assert ast.dump(method,include_attributes=False)==ast.dump(methods[name],include_attributes=False),(path,name)
 for node in ast.walk(tree):
  if isinstance(node,(ast.Import,ast.ImportFrom)):
   roots=[a.name.split('.')[0] for a in node.names] if isinstance(node,ast.Import) else [node.module.split('.')[0]]
   assert set(roots)<= {'torch','unirank'},(path,roots)
