  assert len(layout_calls)==1
  represent.body.remove(layout_calls[0])
  assert ast.dump(represent,include_attributes=False)==ast.dump(orig_methods['_represent'],include_attributes=False)
  normalized=copy.deepcopy(tree)
  for n in normalized.body:
   if isinstance(n,ast.Assign) and any(isinstance(t,ast.Name) and t.id=='CONFIG' for t in n.targets):
    cfg=ast.literal_eval(n.value);cfg['history_order']='canonical';cfg['history_orientation']='forward';n.value=ast.parse(repr(cfg),mode='eval').body
